<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <link href="https://fonts.googleapis.com/css2?family=Anton&family=Cinzel&family=Creepster&family=Orbitron&display=swap" rel="stylesheet">
    <style>
      /* --- 通用样式与CSS变量 --- */
      :root {
        --主色: #d90429;
        --副色: #1a1a1a;
        --背景色: #050505;
        --文本色: #f0f0f0;
        --字体: 'Anton', sans-serif;
        --圆角: 5px;
        --主色-rgb: 217,4,41;
      }
      .状态栏-数据容器 { display: none; }
      .状态栏-容器 {
        width: 100%;
        max-width: 800px; /* 增加最大宽度以适应横向布局 */
        margin: 15px auto;
        background-color: var(--背景色);
        color: var(--文本色);
        font-family: var(--字体);
        border: 2px solid var(--副色);
        border-radius: var(--圆角);
        box-shadow: 0 0 15px rgba(var(--主色-rgb), 0.5);
        overflow: hidden;
      }
      .状态栏-头部 {
        background-color: var(--副色);
        padding: 10px 15px;
        border-bottom: 2px solid var(--主色);
        text-align: center;
        font-size: 1.2rem;
        font-weight: bold;
        text-transform: uppercase;
      }
      .状态栏-内容 {
        display: flex;
        flex-wrap: wrap; /* 允许换行 */
        justify-content: space-around; /* 均匀分布 */
        padding: 15px;
        gap: 15px; /* 块之间的间隙 */
      }
      .数据块 {
        background-color: rgba(255, 255, 255, 0.05);
        border-left: 4px solid var(--主色);
        border-radius: var(--圆角);
        padding: 10px;
        flex: 1; /* 弹性增长 */
        min-width: 220px; /* 最小宽度，防止过度挤压 */
      }
      .数据块-标题 {
        font-weight: bold;
        color: var(--主色);
        margin-bottom: 8px;
        text-transform: capitalize;
        font-size: 1.1em;
      }
      .数据项 {
        display: flex;
        justify-content: space-between;
        padding: 5px 0;
        border-bottom: 1px solid rgba(255, 255, 255, 0.1);
        align-items: flex-start;
      }
      .数据项:last-child { border-bottom: none; }
      .数据键 {
        font-weight: 600;
        text-transform: capitalize;
        padding-right: 10px; /* 键和值之间的间隔 */
        white-space: nowrap;
      }
      .数据值 {
        text-align: right;
        white-space: pre-wrap;
        word-break: break-all;
        flex-shrink: 1;
      }
    </style>
</head>
<body>
    <div class="状态栏-数据容器">$1</div>
    <div class="状态栏-容器">
      <div class="状态栏-头部">欲望监测</div>
      <div class="状态栏-内容">
        <!-- JS将在此处动态生成内容 -->
        <div class="无数据">等待数据流...</div>
      </div>
    </div>
    <script>
    document.addEventListener('DOMContentLoaded', () => {
      const 数据容器 = document.querySelector('.状态栏-数据容器');
      const 内容区域 = document.querySelector('.状态栏-内容');
      const 头部 = document.querySelector('.状态栏-头部');
      if (!数据容器 || !内容区域) return;

      function 解析数据(文本) {
        const 数据 = {};
        const 配置匹配 = 文本.match(/config:\s*([\s\S]*?)(?=\n\[|\n\/\/|\[状态监测_END\])/);
        if (配置匹配) {
            数据.config = {};
            const 配置行 = 配置匹配[1].trim().split('\n');
            配置行.forEach(行 => {
                const 部件 = 行.split(':');
                if (部件.length === 2) {
                    数据.config[部件[0].trim()] = 部件[1].trim();
                }
            });
        }

        const 块正则 = /\[([\u4e00-\u9fa5]+)\]([\s\S]*?)\[\/\1\]/g;
        let 匹配;
        数据.blocks = [];
        while ((匹配 = 块正则.exec(文本)) !== null) {
          const 块名 = 匹配[1];
          const 块内容 = 匹配[2].trim();
          const 条目 = {};
          const 行 = 块内容.split('\n');
          let 当前键 = null;
          let 当前值 = '';

          行.forEach(单行 => {
            const 部件 = 单行.match(/^([^:]+):\s*(.*)/);
            if (部件) {
              if (当前键) 条目[当前键] = 当前值.trim();
              当前键 = 部件[1].trim();
              当前值 = 部件[2].trim();
            } else if (当前键) {
              当前值 += '\\n' + 单行.trim();
            }
          });
          if (当前键) 条目[当前键] = 当前值.trim();
          数据.blocks.push({ name: 块名, items: 条目 });
        }
        return 数据;
      }

      function 渲染数据(数据) {
        if (!数据.blocks || 数据.blocks.length === 0) {
          内容区域.innerHTML = '<div class="无数据">数据已损坏或丢失。</div>';
          return;
        }
        内容区域.innerHTML = '';
        数据.blocks.forEach(块 => {
          const 块容器 = document.createElement('div');
          块容器.className = '数据块';

          let 条目HTML = `<div class="数据块-标题">${块.name}</div>`;
          for (const 键 in 块.items) {
            条目HTML += `
              <div class="数据项">
                <span class="数据键">${键}:</span>
                <span class="数据值">${块.items[键]}</span>
              </div>`;
          }
          块容器.innerHTML = 条目HTML;
          内容区域.appendChild(块容器);
        });
      }

      const 原始数据 = 数据容器.textContent.trim();
      if (原始数据) {
        const 已解析数据 = 解析数据(原始数据);
        渲染数据(已解析数据);
      }
    });
    </script>
  </body>
  </html>
